const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const db={get:(k,d)=>{try{return JSON.parse(localStorage.getItem('bb_'+k))??d}catch{return d}},set:(k,v)=>localStorage.setItem('bb_'+k,JSON.stringify(v))};
$('.theme')?.addEventListener('click',()=>{document.body.classList.toggle('dark');db.set('dark',document.body.classList.contains('dark'))});if(db.get('dark',false))document.body.classList.add('dark');$('.mobile')?.addEventListener('click',()=> $('header nav').classList.toggle('open'));
const done=db.get('done',[]);if($('#homeCompleted'))$('#homeCompleted').textContent=done.length;
$('#catalogSearch')?.addEventListener('input',e=>{let q=e.target.value.toLowerCase().trim();$('#searchResults').innerHTML=q?DATA.filter(x=>(x.subject+' '+x.topic).toLowerCase().includes(q)).slice(0,30).map(x=>`<a href="lessons/${x.slug}.html"><b>${x.topic}</b> · ${x.subject}</a>`).join(''):''});
$$('.check').forEach(c=>$$('button',c).forEach(b=>b.onclick=()=>{let ok=+b.dataset.i===+c.dataset.answer;$('.feedback',c).textContent=ok?'Correct. Great retrieval!':'Not quite. Review the key points, then try again.';$('.feedback',c).style.color=ok?'#087c55':'#a42035'}));
$$('[data-complete]').forEach(b=>{if(done.includes(b.dataset.complete))b.textContent='✓ Completed';b.onclick=()=>{let x=db.get('done',[]);if(!x.includes(b.dataset.complete))x.push(b.dataset.complete);db.set('done',x);b.textContent='✓ Completed'}});
$$('[data-favorite]').forEach(b=>{let fav=db.get('fav',[]);if(fav.includes(b.dataset.favorite))b.textContent='★ Favourite';b.onclick=()=>{let x=db.get('fav',[]),k=b.dataset.favorite;if(x.includes(k))x=x.filter(v=>v!==k);else x.push(k);db.set('fav',x);b.textContent=x.includes(k)?'★ Favourite':'☆ Add to favourites'}});
$$('.notes').forEach(n=>{n.value=db.get('note_'+n.dataset.note,'');n.oninput=()=>{db.set('note_'+n.dataset.note,n.value);$('.saved').textContent='Saved automatically'}});
function fillSubjects(sel){if(sel)sel.innerHTML+=[...new Set(DATA.map(x=>x.subject))].map(x=>`<option>${x}</option>`).join('')}fillSubjects($('#quizSubject'));fillSubjects($('#flashSubject'));
let quiz=[] ,qi=0,score=0,locked=false;$('#startQuiz')?.addEventListener('click',()=>{let s=$('#quizSubject').value,n=+$('#quizLength').value,pool=DATA.filter(x=>s==='All'||x.subject===s).flatMap(x=>x.questions.map(q=>({...q,subject:x.subject,topic:x.topic})));quiz=pool.sort(()=>Math.random()-.5).slice(0,n);qi=score=0;$('#quizApp').classList.remove('hidden');showQuiz()});function showQuiz(){let x=quiz[qi];locked=false;$('#quizCount').textContent=`Question ${qi+1} of ${quiz.length}`;$('#quizScore').textContent=`Score ${score}`;$('#quizBar').style.width=`${(qi+1)/quiz.length*100}%`;$('#quizCategory').textContent=x.subject+' · '+x.topic;$('#quizQuestion').textContent=x.q;$('#quizAnswers').innerHTML=x.o.map((o,i)=>`<button data-i="${i}">${o}</button>`).join('');$('#quizFeedback').textContent='';$('#nextQuiz').classList.add('hidden');$$('#quizAnswers button').forEach(b=>b.onclick=()=>{if(locked)return;locked=true;let ok=+b.dataset.i===x.a;if(ok)score++;$('#quizFeedback').textContent=ok?'Correct!':'Correct answer: '+x.o[x.a];$('#nextQuiz').classList.remove('hidden')})}$('#nextQuiz')?.addEventListener('click',()=>{qi++;if(qi<quiz.length)showQuiz();else{db.set('best',Math.max(score,db.get('best',0)));$('#quizApp').innerHTML=`<h2>Quiz complete</h2><p>You scored <b>${score} / ${quiz.length}</b>.</p><button class="primary" onclick="location.reload()">Try another</button>`}});
let deck=[],fi=0,flipped=false;$('#newDeck')?.addEventListener('click',()=>{let s=$('#flashSubject').value;deck=DATA.filter(x=>s==='All'||x.subject===s).sort(()=>Math.random()-.5).slice(0,20);fi=0;showCard()});function showCard(){let x=deck[fi];if(!x)return;flipped=false;$('#flashMeta').textContent=`${fi+1} / ${deck.length} · ${x.subject}`;$('#flashFront').textContent=x.topic;$('#flashBack').textContent='';}$('#flashCard')?.addEventListener('click',()=>{if(!deck.length)return;let x=deck[fi];flipped=!flipped;$('#flashFront').textContent=flipped?x.facts[0]:x.topic;$('#flashBack').textContent=flipped?'Tap to see the topic':''});$$('[data-rate]').forEach(b=>b.onclick=()=>{if(!deck.length)return;fi=(fi+1)%deck.length;showCard()});
const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];function renderWeek(){let tasks=db.get('tasks',[]);if($('#week'))$('#week').innerHTML=days.map(d=>`<section class="day"><b>${d}</b>${tasks.map((t,i)=>t.day===d?`<div class="task ${t.done?'done':''}" data-task="${i}">${t.title}</div>`:'').join('')}</section>`).join('');$$('[data-task]').forEach(e=>e.onclick=()=>{let x=db.get('tasks',[]),i=+e.dataset.task;x[i].done=!x[i].done;db.set('tasks',x);renderWeek()})}renderWeek();$('#taskForm')?.addEventListener('submit',e=>{e.preventDefault();let x=db.get('tasks',[]);x.push({title:$('#taskTitle').value,day:$('#taskDay').value,done:false});db.set('tasks',x);e.target.reset();renderWeek()});
if($('#statDone')){let fav=db.get('fav',[]),notes=DATA.filter(x=>db.get('note_'+x.slug,'').trim());$('#statDone').textContent=done.length;$('#statBest').textContent=db.get('best',0);$('#statFav').textContent=fav.length;$('#statNotes').textContent=notes.length;$('#doneList').innerHTML=done.length?done.map(k=>{let x=DATA.find(v=>v.slug===k);return `<a href="lessons/${k}.html">✓ ${x?.subject} · ${x?.topic}</a>`}).join(''):'<p>No completed lessons yet.</p>';$('#favList').innerHTML=fav.length?fav.map(k=>{let x=DATA.find(v=>v.slug===k);return `<a href="lessons/${k}.html">★ ${x?.subject} · ${x?.topic}</a>`}).join(''):'<p>No favourites yet.</p>'}$('#reset')?.addEventListener('click',()=>{Object.keys(localStorage).filter(k=>k.startsWith('bb_')).forEach(k=>localStorage.removeItem(k));location.reload()});
